/*selectMasterMpRqBulkQuotationProceList*/ SELECT BURQ_NO, PROJECT_NAME, BUYER_NAME, ATOS_DATE, ATOS_END_DATE, STATUS, AGENT_TYPE_NAME, BURQ_RFQ_NO, ITEM_KEY_ID, RE_LIST_PRICE, CH_LIST_PRICE, PRICE_SUBMIT_USER, ITEM_QTY, TOT_RE_LIST_PRICE, CASE WHEN CAL_PRICE_GAP IS NULL THEN '' WHEN CAL_PRICE_GAP = 0 THEN '-' WHEN CAL_PRICE_GAP < 0 THEN '-'|| TO_CHAR((CAL_PRICE_GAP*-1), 'FM999,999,999') ELSE '+'||TO_CHAR(CAL_PRICE_GAP, 'FM999,999,999') END AS PRICE_GAP, CASE WHEN CAL_GAP_RATE IS NULL THEN '' WHEN CAL_GAP_RATE = 0 THEN '-' WHEN CAL_GAP_RATE < 0 THEN '+'|| TO_CHAR((CAL_GAP_RATE*-1), 'FM999,999,999') || '%' ELSE '-'||TO_CHAR(CAL_GAP_RATE, 'FM999,999,999') || '%' END AS GAP_RATE, CASE WHEN CAL_PRICE_GAP > 0 THEN 'P' WHEN CAL_PRICE_GAP < 0 THEN 'N' ELSE 'Z' END AS PRICE_GAP_FLAG, MAIL_SEND_DATE, AGENT_NAME, AGENT_DESCRIPTION, AGENT_SPECIFICATION, AGENT_MAKER_PART_NO, AGENT_MAKER_NAME, AGENT_MIN_ORDER_QTY, AGENT_PUR_UNIT_QTY, AGENT_UNIT_MEASURE, AGENT_REMARK, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ09' AND CODE = AGENT_PROCESS_TYPE) AS AGENT_PROCESS_TYPE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ10' AND CODE = AGENT_PARCEL_YN) AS AGENT_PARCEL_YN, KEP_DESCRIPTION, KEP_SPECIFICATION, KEP_MAKER_PART_NO, KEP_MAKER_NAME, KEP_MIN_ORDER_QTY, KEP_PUR_UNIT_QTY, KEP_UNIT_MEASURE, SM_DESCRIPTION, SM_SPECIFICATION, SM_MAKER_PART_NO, SM_MAKER_NAME, SM_MIN_ORDER_QTY, SM_PUR_UNIT_QTY, SM_UNIT_MEASURE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ09' AND CODE = SM_PROCESS_TYPE) AS SM_PROCESS_TYPE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ10' AND CODE = SM_PARCEL_YN) AS SM_PARCEL_YN, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = SM_WAREHOUSE_CODE) AS SM_WAREHOUSE, PO_CNT, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = MAIN_BUYER) AS MAIN_BUYER, AGENT_MNG_USER_NAME, SG_NAME, SM_USER_NAME, BUYER, AGENT, SG_ID, GPL_YN, AGENT_TYPE, CNT2, CNT3, AGENT_MNG_USER_ID, AGENT_MNG_USER_TEL, ITEM_TYPE_NAME FROM ( SELECT A.BURQ_NO, (SELECT PROJECT_NAME FROM KEP_BURQ_MNG C WHERE C.BURQ_NO = A.BURQ_NO) AS PROJECT_NAME, NVL((SELECT COMORG_NAME FROM BYCAORGL WHERE COMORG_CODE = A.BYIT_COMORG_CODE), (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BUYER)) AS BUYER_NAME, B.ATOS_DATE, B.ATOS_END_DATE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ04' AND CODE = NVL(B.STATUS,'K03')) AS STATUS, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ03' AND CODE = B.AGENT_TYPE) AS AGENT_TYPE_NAME, B.BURQ_RFQ_NO, A.ITEM_KEY_ID, A.RE_LIST_PRICE, B.CH_LIST_PRICE, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = B.PRICE_SUBMIT_USER) AS PRICE_SUBMIT_USER, A.ITEM_QTY, (A.ITEM_QTY * A.RE_LIST_PRICE) AS TOT_RE_LIST_PRICE, DECODE(NVL(B.CH_LIST_PRICE, 0), 0, NULL, (B.CH_LIST_PRICE - A.RE_LIST_PRICE) * A.ITEM_QTY) AS CAL_PRICE_GAP, DECODE(NVL(B.CH_LIST_PRICE, 0), 0, NULL, ( ( ( A.RE_LIST_PRICE - B.CH_LIST_PRICE ) / A.RE_LIST_PRICE ) ) * 100) AS CAL_GAP_RATE, (SELECT MAX(TO_CHAR(SEND_PROC_DATE,'YYYYMMDD')) FROM DM_SEND_HIST HIST, DM_SEND_INFO INFO WHERE INFO.DM_ID = HIST.DM_ID AND MAILFORM_ID = 'DM_BURQ_MS' AND SENT_AGENT = B.AGENT AND SENT_QUOTATION_NO = B.BURQ_NO AND SENT_QUOTATION_SEQ = B.BURQ_RFQ_NO AND SEND_TYPE = 'M') AS MAIL_SEND_DATE, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = B.AGENT) AS AGENT_NAME, AGENT_DESCRIPTION, AGENT_SPECIFICATION, AGENT_MAKER_PART_NO, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M104' AND CODE = B.AGENT_MAKER_CODE) AS AGENT_MAKER_NAME, AGENT_MIN_ORDER_QTY, AGENT_PUR_UNIT_QTY, AGENT_UNIT_MEASURE, AGENT_PROCESS_TYPE, AGENT_PARCEL_YN, AGENT_REMARK, -- 고객사 카탈로그 정보 B.KEP_DESCRIPTION, B.KEP_SPECIFICATION, B.KEP_MAKER_PART_NO, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M104' AND CODE = B.KEP_MAKER_CODE) AS KEP_MAKER_NAME, B.KEP_MIN_ORDER_QTY, B.KEP_PUR_UNIT_QTY, B.KEP_UNIT_MEASURE, -- KEP 품목정보 B.SM_DESCRIPTION, B.SM_SPECIFICATION, B.SM_MAKER_PART_NO, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M104' AND CODE = B.SM_MAKER_CODE) AS SM_MAKER_NAME, B.SM_MIN_ORDER_QTY, B.SM_PUR_UNIT_QTY, B.SM_UNIT_MEASURE, B.SM_PROCESS_TYPE, B.SM_PARCEL_YN, B.SM_WAREHOUSE_CODE, A.PO_CNT, A.MAIN_BUYER, (SELECT MIN(USER_NAME_LOC) FROM ICOMLUSR WHERE LEGACY_USER_ID = AGENT_MNG_USER_ID AND STATUS <> 'D') AS AGENT_MNG_USER_NAME, (SELECT SG_NAME FROM KEPSGMG SG WHERE SG.SG_ID = A.SG_ID) AS SG_NAME, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = SM_USER_ID) AS SM_USER_NAME, NVL(A.BYIT_COMORG_CODE,A.BUYER) AS BUYER, B.AGENT AS AGENT, A.SG_ID AS SG_ID, DECODE((SELECT COUNT(*) FROM ICOMBYIT BYIT WHERE 'KRGPLK0001' = A.BUYER AND BYIT.BUYER_ITEM_NO = A.BUYER_ITEM_NO),0,'N','Y') AS GPL_YN, AGENT_TYPE, DECODE(B.STATUS, 'S1' , 1, 0) AS CNT2, -- 견적제출 DECODE(B.STATUS, 'K1' , 1, 0) AS CNT3, -- 미회신 (SELECT USER_ID FROM ICOMLUSR WHERE COM_CODE = 'KRKORE0001' AND LEGACY_USER_ID = AGENT_MNG_USER_ID AND USER_ID NOT LIKE 'O%') AS AGENT_MNG_USER_ID, (SELECT PHONE_NUMBER FROM ICOMLUSR WHERE COM_CODE = 'KRKORE0001' AND LEGACY_USER_ID = AGENT_MNG_USER_ID AND STATUS <> 'D' AND USER_ID NOT LIKE 'O%') AS AGENT_MNG_USER_TEL, -- 사무용품 아이디 제외 (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ05' AND CODE = B.ITEM_TYPE AND FLAG = 'Y') AS ITEM_TYPE_NAME FROM KEP_BURQ_ITEM A, KEP_BURQ_RFQ B WHERE 1=1 AND A.BURQ_NO = B.BURQ_NO AND A.ITEM_KEY_ID = B.ITEM_KEY_ID
AND B.BURQ_NO = #{st_burq_no}
AND B.AGENT = #{st_agent_code}
) X WHERE 1=1
AND AGENT_MNG_USER_NAME = #{st_mng_name}
AND SM_USER_NAME = #{st_mng_name}
AND TO_CHAR(ATOS_DATE,'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date}
AND ATOS_END_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND BUYER_NAME LIKE '%'||UPPER(#{st_buyer_name}) || '%'
AND ITEM_KEY_ID = #{st_item_key_id}
AND SG_ID = #{st_c_sg_id}
AND (UPPER(KEP_MAKER_NAME) LIKE '%'||UPPER(#{st_maker_name})||'%' OR UPPER(SM_MAKER_NAME) LIKE '%'||UPPER(#{st_maker_name})||'%' OR UPPER(AGENT_MAKER_NAME) LIKE '%'||UPPER(#{st_maker_name})||'%' )
AND BURQ_RFQ_NO = #{st_burq_rfq_no}
AND STATUS IN (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ04' AND CODE IN
#{status}
AND FLAG = 'Y')
AND (UPPER(KEP_DESCRIPTION) LIKE '%'||UPPER(#{st_description})||'%' OR UPPER(SM_DESCRIPTION) LIKE '%'||UPPER(#{st_description})||'%' OR UPPER(AGENT_DESCRIPTION) LIKE '%'||UPPER(#{st_description})||'%' )
AND (UPPER(KEP_SPECIFICATION) LIKE '%'||UPPER(#{st_specification})||'%' OR UPPER(SM_SPECIFICATION) LIKE '%'||UPPER(#{st_specification})||'%' OR UPPER(AGENT_SPECIFICATION) LIKE '%'||UPPER(#{st_specification})||'%' )
AND (UPPER(KEP_MAKER_PART_NO) LIKE '%'||UPPER(#{st_model_name})||'%' OR UPPER(SM_MAKER_PART_NO) LIKE '%'||UPPER(#{st_model_name})||'%' OR UPPER(AGENT_MAKER_PART_NO) LIKE '%'||UPPER(#{st_model_name})||'%' )
AND GPL_YN = #{st_gpl_yn}
AND AGENT_TYPE = #{st_agent_type}

