/* updateBulkQuotationProceRFQ */
UPDATE KEP_BURQ_RFQ RFQ
SET STATUS = 'K2'
WHERE ATOS_END_DATE < TO_CHAR(SYSDATE,'YYYYMMDD') 
AND STATUS <> 'K2'




AND TO_CHAR(ATOS_DATE,'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date}         





AND ATOS_END_DATE BETWEEN #{st_from_date} AND #{st_to_date}   





AND BURQ_NO = #{st_burq_no}





AND AGENT = #{st_agent_code}  





AND (SELECT MIN(USER_NAME_LOC) FROM ICOMLUSR WHERE LEGACY_USER_ID = (SELECT AGENT_MNG_USER_ID FROM KEP_BURQ_ITEM WHERE BURQ_NO = RFQ.BURQ_NO AND ITEM_KEY_ID = RFQ.ITEM_KEY_ID)) = #{st_agent_mng_name}

