/*selectMasterMpRqBulkQuotationDmHist*/
SELECT	TO_CHAR(SEND_PROC_DATE,'YYYY-MM-DD HH24:MI:SS') AS SEND_DATE,
	(SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = SEND_USER_ID) AS SEND_USER_NAME,
	RECV_ADDRESS
FROM DM_SEND_HIST HIST, DM_SEND_INFO INFO
WHERE INFO.DM_ID = HIST.DM_ID
AND MAILFORM_ID = 'DM_BURQ_MS'
AND SENT_AGENT  = #{AGENT}
AND SENT_QUOTATION_NO = #{BURQ_NO}
AND SENT_QUOTATION_SEQ = #{BURQ_RFQ_NO}
AND SEND_TYPE = 'M'

/*selectMasterMpRqBulkQuotationProceExcelList*/ SELECT * FROM ( SELECT MAX(A.ITEM_KEY_ID) AS ITEM_KEY_ID, MAX(A.BURQ_NO) AS BURQ_NO, MAX((SELECT PROJECT_NAME FROM KEP_BURQ_MNG C WHERE C.BURQ_NO = A.BURQ_NO)) AS PROJECT_NAME, MAX(NVL((SELECT COMORG_NAME FROM BYCAORGL WHERE COMORG_CODE = A.BYIT_COMORG_CODE), (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BUYER))) AS BUYER_NAME, MAX(B.ATOS_END_DATE) AS ATOS_END_DATE, MAX((SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ04' AND CODE = NVL(B.STATUS,'K03'))) AS STATUS, MAX(B.BURQ_RFQ_NO) AS BURQ_RFQ_NO, SUM(CASE WHEN B.STOA_DATE IS NOT NULL THEN 1 ELSE 0 END)||'/'||SUM(CASE WHEN B.STATUS = 'K1' THEN 1 ELSE 0 END) AS RECEIPT_CNT, MAX((SELECT USER_NAME_LOC FROM ICOMLUSR WHERE LEGACY_USER_ID = AGENT_MNG_USER_ID AND COM_CODE = 'KRKORE0001' AND STATUS <> 'D' AND USER_ID NOT LIKE 'O%')) AS AGENT_MNG_USER_NAME, MAX((SELECT SG_NAME FROM KEPSGMG SG WHERE SG.SG_ID = A.SG_ID)) AS SG_NAME, MAX((SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = SM_USER_ID)) AS SM_USER_NAME, MAX(DECODE((SELECT COUNT(*) FROM ICOMBYIT BYIT WHERE 'KRGPLK0001' = A.BUYER AND BYIT.BUYER_ITEM_NO = A.BUYER_ITEM_NO),0,'N','Y')) AS GPL_YN,
-- 고객사 카탈로그 정보 MAX(B.KEP_DESCRIPTION) AS KEP_DESCRIPTION, MAX(B.KEP_SPECIFICATION) AS KEP_SPECIFICATION, MAX(B.KEP_MAKER_PART_NO) AS KEP_MAKER_PART_NO, MAX((SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M104' AND CODE = B.KEP_MAKER_CODE)) AS KEP_MAKER_NAME, MAX(B.KEP_MIN_ORDER_QTY) AS KEP_MIN_ORDER_QTY, MAX(B.KEP_PUR_UNIT_QTY) AS KEP_PUR_UNIT_QTY, MAX(B.KEP_UNIT_MEASURE) AS KEP_UNIT_MEASURE, -- KEP 품목정보 MAX(B.SM_DESCRIPTION) AS SM_DESCRIPTION, MAX(B.SM_SPECIFICATION) AS SM_SPECIFICATION, MAX(B.SM_MAKER_PART_NO) AS SM_MAKER_PART_NO, MAX((SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M104' AND CODE = B.SM_MAKER_CODE)) AS SM_MAKER_NAME, MAX(B.SM_MIN_ORDER_QTY) AS SM_MIN_ORDER_QTY, MAX(B.SM_PUR_UNIT_QTY) AS SM_PUR_UNIT_QTY, MAX(B.SM_UNIT_MEASURE) AS SM_UNIT_MEASURE,
MAX(A.PO_CNT) AS PO_CNT, MAX(A.ITEM_QTY) AS ITEM_QTY, MAX(A.MAIN_BUYER) AS MAIN_BUYER, MAX(A.RE_LIST_PRICE) AS RE_LIST_PRICE FROM KEP_BURQ_ITEM A, KEP_BURQ_RFQ B WHERE A.BURQ_NO = B.BURQ_NO AND A.ITEM_KEY_ID = B.ITEM_KEY_ID
AND TO_CHAR(ATOS_DATE,'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date}
AND ATOS_END_DATE BETWEEN #{st_from_date} AND #{st_to_date}
GROUP BY A.BURQ_NO, A.ITEM_KEY_ID ) AA,( SELECT * FROM ( SELECT CH_LIST_PRICE, AGENT, BURQ_NO AS RFQ_BURQ_NO, ITEM_KEY_ID AS RFQ_ITEM_KEY_ID FROM KEP_BURQ_RFQ ) PIVOT ( MAX(CH_LIST_PRICE) FOR AGENT IN
'${Map.AGENT}'
) ) BB WHERE AA.BURQ_NO = BB.RFQ_BURQ_NO AND AA.ITEM_KEY_ID = BB.RFQ_ITEM_KEY_ID
AND AA.BURQ_NO = #{st_burq_no}
