AND SG_ID = #{st_c_sg_id}
AND UPPER(MAKER_NAME) LIKE '%'||UPPER(#{st_maker_name})||'%'
AND BURQ_RFQ_NO = #{st_burq_rfq_no}
AND STATUS IN (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ04' AND CODE IN
