		/*selectAgent*/
		SELECT DISTINCT (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = AGENT) AS AGENT_NAME, AGENT
		FROM (
			SELECT	(SELECT USER_NAME_LOC FROM ICOMLUSR WHERE LEGACY_USER_ID = AGENT_MNG_USER_ID) AS AGENT_MNG_USER_NAME, 
