					DECODE((SELECT COUNT(*) FROM ICOMBYIT BYIT WHERE 'KRGPLK0001' = A.BUYER AND BYIT.BUYER_ITEM_NO = A.BUYER_ITEM_NO),0,'N','Y') AS GPL_YN,
